      const { data, error } = await client.from("recommendation_runs").insert({
        user_id: user.id,
        input_mode: inputMode,
        input_data: inputData,
        results,
        model_name: modelName,
        model_version: modelVersion,
      }).select("id").single();
      if (error) throw error;
